// fallout/ai/playercharacter.cpp: PlayerView, PlayerCharacter_StandIn, PlayerCharacter, PlayerStub and more (251 functions)

#include "PlayerCharacter.h"

// Returns the total actor value by summing the base value and temporary, script, and damage modifiers when an actor base exists.
// @fnv 0x0093ac20
int PlayerCharacter::GetActorValue(ActorValue::Index actorValue)
{
    if (GetActorBase())
    {
        return GetBaseActorValue(actorValue) + static_cast<int>(GetActorValueModifierAmount(TEMPORARY, actorValue)) +
               static_cast<int>(GetActorValueModifierAmount(SCRIPTS, actorValue)) + static_cast<int>(GetActorValueModifierAmount(DAMAGE, actorValue));
    }
    return 0;
}

// Returns the current value of an actor value from the specified modifier group (damage, temporary, or scripts).
// @fnv 0x0094c3d0
float PlayerCharacter::GetActorValueModifierAmount(ModifierGroup modifier, ActorValue::Index actorValue)
{
    float value = 0.0f;
    switch (modifier)
    {
    case DAMAGE:
        switch (actorValue)
        {
        case ActorValue::ActorValue__Index_HEALTH:
            value = ActorValueState;
            break;
        default:
            value = ActorValueData[actorValue];
            break;
        }
        break;
    case TEMPORARY:
        value = ActorValueModifierData[actorValue];
        break;
    case SCRIPTS:
        value = m_afScriptModifiers[actorValue];
        break;
    }
    return value;
}

