// Applies a delta to a tracked value after CanModify and Adjust checks, triggering heartbeat audio and damage effects when the value is 16.
// @fnv 0x0093b7a0
void PlayerLike::FUN_0093b7a0(int av, float delta, PlayerLike* source)
{
    if (!CanModify(av, delta))
        return;
    if (FUN_00406d70(av, 0x100))
        return;
    float oldRatio = av == 16 ? values.current(16) / values.maximum(16) : 1.0;
    delta = Adjust(av, delta, source);
    float oldValue = IsTracked(av) ? values.current(av) : 0.0f;
    int aMode = FUN_00406d70(av, 0x200) ? 1 : 0;
    Modify(2, av, delta, aMode);
    NotifyValue(av);
    if (av == 16)
    {
        float fNewRatio = values.current(16) / values.maximum(16);
        if (delta < 0.0)
            DamageEffect(source, delta);
        if (fNewRatio <= 0.0 || fNewRatio > *originalRuntimeFloatSetting1002.Float())
            heartbeat.Fade(1000);
        else if (fNewRatio <= *originalRuntimeFloatSetting1002.Float() &&
                 fNewRatio > *originalRuntimeFloatSetting1003.Float() &&
                 (oldRatio <= *originalRuntimeFloatSetting1003.Float() ||
                  oldRatio > *originalRuntimeFloatSetting1002.Float()))
        {
            heartbeat.Stop();
            heartbeat.Reset();
            heartbeat = Audio::GetSingleton()->GetSoundHandleByEditorID("UIHealthHeartbeatALP", 0x31);
            heartbeat.Play(true);
        }
        else if (oldRatio > *originalRuntimeFloatSetting1003.Float() &&
                 fNewRatio <= *originalRuntimeFloatSetting1003.Float())
        {
            heartbeat.Stop();
            heartbeat.Reset();
            heartbeat = Audio::GetSingleton()->GetSoundHandleByEditorID("UIHealthHeartbeatBLP", 0x31);
            heartbeat.Play(true);
        }
    }
    Update(av, false);
    NotifyChange(this ? &values : 0, av, oldValue, delta, source ? &source->values : 0);
}

