// If sounds[index] is valid, restarts it at the current position; otherwise creates it from the sound for index.
// @fnv 0x00962030
void OwnerS::PlaySound(int index)
{
    if (sounds[index].IsValid())
    {
        sounds[index].Stop();
        PosS pos = *GetPos();
        sounds[index].SetPosition(pos.x, pos.y, pos.z);
        sounds[index].SetObject(Get3D());
        sounds[index].Play(false);
    }
    else
    {
        TESSoundS* sound = GetSoundForIndex(index);
        if (sound)
        {
            sounds[index] = MakeSound(sound->GetFormID(), 0, 2, 1);
        }
    }
}

